var CRE=[{"src":"AU","saves":{},"skills":"","vuln":"","gear":"","cr":"None","xp":0,"reactions":[],"init":"","n":"Vestige Companion","size":"Small","type":"Celestial, Fiend, or Undead","al":"Neutral","ac":"13 + MOD","hp":"4 + 4*LV","hd":"LVd6","speed":"5 ft., Fly 30 ft. (hover)","ab":{"STR":1,"DEX":14,"CON":10,"INT":15,"WIS":15,"CHA":16},"res":"","imm":"Charmed, Frightened, Prone","senses":"Darkvision 60 ft., Passive Perception 12","lang":"Speaks the languages you know","pb":"PB","initNote":"Acts on your turn. It takes only the Dodge action unless you command it with a Bonus Action","traits":[["Pact Bond","Add {PB} to any ability check or saving throw the vestige makes."]],"actions":[["Vestige's Strike","Melee or Ranged Attack Roll: {ATK} to hit (your spell attack modifier), reach 5 feet or range 60 feet. Damage on a hit: {1d6 + 3 + MOD} Fire (Fiend), Necrotic (Undead), or Radiant (Celestial)."]],"bonus":[],"tags":["companion"],"class":"Warlock (Vestige Patron)","group":"Class","variants":[{"v":"Celestial","type":"Celestial","res":"Radiant","bonus":[["Divine Power: Healing Touch (1/Day)","The vestige touches another creature. The target regains {2d8 + MOD} Hit Points, and one of these conditions ends on it: Blinded, Deafened, or Poisoned."]]},{"v":"Fiend","type":"Fiend","res":"Fire","bonus":[["Divine Power: Fiendish Swap (1/Day)","If you and the vestige are within 60 feet of each other, you both teleport and swap places."]]},{"v":"Undead","type":"Undead","res":"Necrotic","bonus":[["Divine Power: Cursed Invocation (1/Day)","The vestige curses a creature you can see within 30 feet of it for 1 minute. The target has Disadvantage on attack rolls against you and the vestige."]]}]},{"src":"RHW","saves":{},"skills":"","vuln":"","gear":"","cr":"None","xp":0,"reactions":[],"init":"","n":"Reanimated Companion","size":"Medium","type":"Undead","al":"Neutral","ac":"10 + MOD","hp":"5 + 5*LV","hd":"LVd8","speed":"30 ft.","ab":{"STR":11,"DEX":10,"CON":16,"INT":4,"WIS":10,"CHA":6},"res":"Necrotic, Poison","imm":"Lightning; Charmed, Exhaustion, Poisoned","senses":"Blindsight 60 ft., Passive Perception 10","lang":"Understands the languages you know","pb":"PB","initNote":"Acts on your turn. It takes only the Dodge action unless you command it with a Bonus Action","traits":[["Death Burst","When the companion dies, it explodes. Dexterity Saving Throw (DC {DC}), each creature in a 10-foot Emanation from the companion. Failure: {(2+2*min(1,floor(LV/9)))d4} Necrotic damage. Success: half damage."],["Lightning Absorption","Whenever the companion takes Lightning damage, it regains Hit Points equal to the damage dealt."]],"actions":[["Dreadful Swipe","Melee Attack Roll: {ATK} to hit (your spell attack modifier), reach 5 feet. Damage on a hit: {1d4 + MOD} Necrotic, and the target can't make Opportunity Attacks until the start of its next turn."]],"bonus":[],"tags":["undead","companion"],"class":"Artificer (Reanimator)","group":"Class","variants":[{"v":"Ferocity","traits":[["Ferocity","Dreadful Swipe uses a d6 for its damage instead of a d4."]]},{"v":"Arcane Conduit","traits":[["Arcane Conduit","You can cast spells as if you were in the companion's space, using your own senses. Once per turn, when you cast an Artificer Evocation or Necromancy spell that deals damage while the companion is within 120 feet, add {MOD} to one damage roll of the spell."]]},{"v":"Bloated (level 9)","size":"Large","traits":[["Bloated","When Dreadful Swipe hits a Large or smaller creature, it is pushed up to 10 feet away. Add {MOD} to the damage of Death Burst."]]},{"v":"Gaunt (level 9)","speed":"45 ft., Climb 45 ft.","traits":[["Gaunt","It climbs difficult surfaces, ceilings included, with no ability check. A creature of your choice that starts its turn within 10 feet of it makes a Wisdom saving throw (DC {DC}) or is Frightened until the start of its next turn."]]},{"v":"Moist (level 9)","speed":"30 ft., Swim 30 ft.","traits":[["Moist","It squeezes through spaces as narrow as 1 inch with no extra movement. When a creature within 10 feet hits it with an attack roll, the attacker takes {MOD} Acid damage."]]}]}];
